# ---------------------------------------------------------------- [1~3] 발표
G1 = '발표 · 표현의 적절성'
P1 = ('<p class="hd"><b>[1~3]</b> 다음은 학생이 과제 수행 후 실시한 발표이다.</p>'
      '<p>안녕하세요? 지난 시간에 언어의 공공성에 대해 배운 것 기억하시나요? 발표나 토론 같은 공식적인 담화에 참여하거나 매체를 통해 불특정 다수와 소통하는 상황에서는 언어의 공공성에 유의해야 한다는 것을 배웠습니다. 상황에 적절한 어휘나 문장 표현 등을 사용하는 것은 언어의 공공성을 갖추는 데 도움을 주는데요. 이는 화자가 의미를 제대로 전달하고 청자가 화자를 믿을 만한 사람으로 인식하는 데 영향을 주기 때문입니다. 저는 이러한 표현의 적절성에 대해 조사한 내용을 발표하겠습니다.</p>'
      '<p>지금부터 어휘와 문장 차원으로 나누어 설명하겠습니다. (목소리를 가다듬고) 어휘는 베리 시그니피컨트합니다. (반응을 살피며) 조금 의아해하시네요. 그럼 이렇게 말씀드려 볼게요. (느린 속도로) 어휘는 매우 중요합니다. 어떤 표현이 더 잘 이해되세요? (고개를 끄덕이며) 네, 다들 후자라고 하시네요. 외국어를 불필요하게 사용하면 의사소통 상황에서 청자에게 의미를 제대로 전달하기 어렵습니다. 한편, 제가 이 자리에서 \'벚치다\' 같은 비속어나 \'레알\' 같은 유행어를 사용하는 것도 적절하지 않을 것입니다. 왜냐하면 다수를 대상으로 하는 발표에서 격식에 맞지 않는 가벼운 표현을 사용하면 여러분이 저를 신뢰하기 어려운 사람으로 여길 수 있기 때문입니다.</p>'
      '<p>어휘뿐 아니라 문장에서도 상황에 적절한 표현이 중요합니다. 저는 토론 수업에서 \'안전이 편의보다 중요할 것 같아 보입니다.\'라고 말했다가, 입장이 명확하지 않고 자신감이 없어 보여 설득력이 떨어진다는 동료 평가를 받은 적이 있습니다. 그래서 <u>㉠말하는 내용에 대한 확신의 정도를 드러내는 표현</u>들을 찾아보니, 제가 사용한 \'-ㄹ 것 같다\'와 \'-아 보이다\'가 모두 확신의 정도가 낮은 표현들이었습니다. 그러다 보니 주장을 밝히는 데에 다소 적합하지 않았던 것입니다. 사실 저는 지나치게 단정적인 표현을 피함으로써 상대를 존중하는 태도를 나타내고 싶었지만, 토론에서는 이런 표현이 적절하지 않을 수도 있음을 알게 되었습니다. 여러분도 일상에서 다수와 소통하는 담화에 참여하고 있으니, 상황에 적절한 문장을 사용할 필요가 있습니다.</p>'
      '<p>지금까지 표현의 적절성을 어휘 차원과 문장 차원으로 나누어 살펴보았습니다. (목소리를 높여) 상황에 적절한 표현은 의미를 명확하게 전달하고, 화자에 대한 신뢰성을 높인다는 점에서 중요합니다. 발표를 들은 여러분이 표현의 적절성에 관심을 갖고 원활하게 소통하는 화자가 되기를 바랍니다. 감사합니다.</p>')


def add(code, sub, typ, lv, body, opts, ans, exp, passage=None, grp=None, ref=None, pts=None, core=None):
    d = dict(code=code, sub=sub, type=typ, lv=lv, src=SRC % int(code.split('-')[1]), body=body, opts=opts, ans=ans, exp=exp)
    if passage: d['passage'] = passage
    if grp: d['grp'] = grp
    if ref: d['ref'] = ref
    if pts: d['pts'] = pts
    if core: d['core'] = core
    ITEMS.append(d)


add('H26-001', 'Ⅰ-A', '발표의 말하기 방식 파악', '중', p('위 발표자의 말하기 방식으로 가장 적절한 것은?'),
    ['대비되는 발화를 실연하여 청중의 관심을 유도하고 있다.', '비언어적 표현을 사용하여 발표의 절차를 안내하고 있다.', '정보의 출처를 언급하여 청중의 궁금증을 해소하고 있다.', '같은 내용을 거듭 질문하여 청중의 답변을 끌어내고 있다.', '구체적인 통계를 제시하여 발표의 필요성을 부각하고 있다.'], 1,
    ['① 옳다. \'베리 시그니피컨트합니다\'와 \'매우 중요합니다\'를 차례로 말해 두 표현을 대비하고, 청중의 반응을 살피며 관심을 유도했다.', '② 옳지 않다. 목소리·속도·고개 끄덕임은 절차 안내가 아니라 강조와 반응 확인을 위한 표현이다.', '③ 옳지 않다. 정보의 출처를 밝힌 부분이 없다.', '④ 옳지 않다. "어떤 표현이 더 잘 이해되세요?"를 한 번 물었을 뿐 같은 내용을 거듭 질문하지 않았다.', '⑤ 옳지 않다. 구체적인 통계가 제시되지 않았다.'],
    passage=P1, grp='H26-A', ref=[3], core='발표의 말하기 방식(실연·질문·반응 확인·예시·통계·출처)은 지문의 구체적 행위로 확인한다.')

add('H26-002', 'Ⅰ-A', '발표 계획의 반영 여부', '중',
    p('다음은 위 발표를 하기 위해 학생이 세운 계획이다. 발표에 반영되지 않은 것은?'),
    ['<b>[도입]</b> 지난 시간에 배운 내용을 환기하고, 발표의 화제가 \'표현의 적절성\'임을 소개해야겠다.', '<b>[전개]</b> \'표현의 적절성\'을 두 가지 차원으로 나누어 예를 중심으로 설명해야겠다.', '<b>[전개]</b> \'표현의 적절성\'의 개념이 변하는 양상을 그와 관련된 예를 들어 분석해야겠다.', '<b>[전개]</b> 실제 경험을 예로 들어 \'표현의 적절성\'이 발표를 듣는 학생들과 관련이 있음을 제시해야겠다.', '<b>[정리]</b> 발표의 내용을 요약하고, 발표를 듣는 학생들에게 \'표현의 적절성\'과 관련하여 바라는 바를 언급해야겠다.'], 3,
    ['① 반영되었다. "지난 시간에 언어의 공공성에 대해 배운 것 기억하시나요?"로 내용을 환기하고 화제를 소개했다.', '② 반영되었다. 어휘와 문장 차원으로 나누어 예를 들어 설명했다.', '③ 반영되지 않았다. 표현의 적절성이라는 개념이 시간에 따라 변하는 양상을 분석한 부분은 없다.', '④ 반영되었다. 토론 수업에서 \'안전이 편의보다 중요할 것 같아 보입니다\'라고 말했던 경험을 예로 들었다.', '⑤ 반영되었다. 마지막에 내용을 요약하고 "원활하게 소통하는 화자가 되기를 바랍니다"라고 바람을 밝혔다.'],
    passage=P1, grp='H26-A', ref=[2], core='발표 계획과 발표문의 실제 행위(환기·설명·분석·요약)를 하나씩 대응시킨다.')

add('H26-003', 'Ⅰ-A', '확신 정도를 드러내는 표현', '상',
    p('〈보기〉는 위 발표 후 이어진 수업 내용의 일부이다. ㉠과 관련해 [A]에 들어갈 학생의 말로 적절하지 않은 것은?') +
    bogi(['<b>선생님</b>: 발표 잘 들었어요. 발표 내용 중, 말하는 내용에 대한 확신의 정도를 드러내는 표현에 대해 궁금해할 것 같네요. 확신의 정도를 드러내기 위해 동사, 부사, 의존 명사, 보조 용언, 인용절 등을 사용할 수 있는데, 상황에 따라 어휘나 문법 요소를 적절하게 선택할 수 있어요. 화면은 \'안전이 편의보다 중요하다\'라는 내용에, 앞서 언급된 표현을 더해 확신의 정도에 변화를 준 문장들입니다. 확신의 정도와 관련된 표현을 찾아 설명해 볼까요?',
           'ⓐ 저에게는 안전이 편의보다 중요한 듯 이해되고 있습니다.', 'ⓑ 저는 안전이 편의보다 중요하다고 믿게 됐습니다.', 'ⓒ 저는 대체로 안전이 편의보다 중요하다고 봅니다.', 'ⓓ 분명히 안전이 편의보다 중요한 법입니다.', '<b>학생</b>: [A]']),
    ['ⓐ는 ⓑ와 달리 보조 용언을 써서 확신의 정도를 드러냈어요.', 'ⓐ는 ⓒ와 달리 피동 접사가 있는 동사를 써서 확신의 정도를 드러냈어요.', 'ⓐ와 ⓓ는 모두 의존 명사를 썼는데, 의존 명사가 나타내는 확신의 정도는 ⓓ가 더 높아요.', 'ⓑ와 ⓒ는 인용절을 썼다는 점은 같지만, 인용절 바로 뒤의 동사가 나타내는 확신의 정도는 ⓑ가 더 높아요.', 'ⓒ와 ⓓ는 모두 부사를 썼는데, 부사가 나타내는 확신의 정도는 ⓓ가 더 높아요.'], 1,
    ['① 적절하지 않다. ⓐ는 "이해되고 있습니다"의 "-고 있다", ⓑ도 "믿게 됐습니다"의 "-게 되다"라는 보조 용언을 썼으므로 ⓐ만의 특징이 아니다.', '② 적절하다. ⓐ의 "이해되다"는 접미사 "-되-"가 붙은 피동사이고 ⓒ의 "보다"는 능동사이다.', '③ 적절하다. ⓐ의 "듯"과 ⓓ의 "법"은 모두 의존 명사이며 "법"이 "듯"보다 확신이 높다.', '④ 적절하다. 둘 다 인용절("중요하다고")을 썼고 동사 "믿다"가 "보다"보다 확신이 높다.', '⑤ 적절하다. "대체로"보다 "분명히"가 확신이 높다.'],
    passage=P1, grp='H26-A', ref=[4], core='확신의 정도: 동사(믿다>보다), 부사(분명히>대체로), 의존 명사(법>듯), 보조 용언·피동은 완곡.')

