add('H26-004', 'Ⅰ-B', '토의 사회자의 역할', '중', p('위 토의에 나타난 \'사회자\'의 역할로 적절하지 않은 것은?'),
    ['토의의 배경과 주제를 제시하며 토의를 시작한다.', '토의자들의 발언 내용을 정리하며 토의를 이어 간다.', '토의자들의 발언 순서를 조정하여 발언 기회를 분배한다.', '토의 결과를 활용할 계획을 밝히고 토의 참여를 독려한다.', '토의자에게 질문하여 발언에 사용된 용어의 개념을 확인한다.'], 3,
    ['① 적절하다. 지난달 사고 4건이라는 배경과 "후문 계단에서 발생하는 안전사고를 줄이기 위한 방법"이라는 주제를 밝히며 시작했다.', '② 적절하다. "지금까지 계단 재시공, 미끄럼 방지 패드 부착, 난간 보수 이렇게 세 가지 의견이 제시되었습니다"라고 정리했다.', '③ 적절하지 않다. 사회자는 "이어서 각자 준비한 의견을 계속 말씀해 주시겠습니까?"라고 했을 뿐 발언할 사람이나 순서를 지정·조정하지 않았다.', '④ 적절하다. "학교에 건의하려고" 한다며 결과 활용 계획을 밝히고 "적극적으로 의견을 말씀해 주십시오"라고 독려했다.', '⑤ 적절하다. "단너비가 무엇인가요?"라고 물어 용어의 개념을 확인했다.'],
    passage=P2, grp='H26-B', ref=[1], core='사회자는 주제 제시·정리·참여 독려·용어 확인을 하지만 의견을 내거나 순서를 임의로 정하지 않는 경우가 있다. 지문의 발화로 하나씩 확인한다.')

add('H26-005', 'Ⅰ-B', '토의 참여자의 발언 분석', '상', p('[A]를 이해한 내용으로 적절하지 않은 것은?'),
    ['\'학생 1\'은 대안을 제시할 때 조사 내용을 근거로 삼아 자신의 의견을 피력하고 있다.', '\'학생 2\'는 \'학생 1\'이 제시한 대안이 지닌 현실적 어려움을 지적하고 있다.', '\'학생 3\'은 토의 준비 과정에서 알게 된 정보를 바탕으로 \'학생 2\'의 대안을 보강하고 있다.', '\'학생 4\'는 \'학생 1\'이 제시한 대안의 실행 가능성이 높다는 점에 공감하며 자신의 대안을 제시하고 있다.', '\'학생 1\'은 \'학생 4\'가 제시한 대안에 대해 효율성의 측면에서 긍정적으로 평가하고 있다.'], 4,
    ['① 적절하다. "학생들에게 조사해 보니 … 단너비가 좁은 계단의 구조를 사고의 원인으로 꼽았습니다"라는 조사 결과를 근거로 계단 재시공을 제안했다.', '② 적절하다. 학생 2는 공간 부족과 공사 기간 중 불편을 들어 재시공이 어렵다고 했다.', '③ 적절하다. 학생 3은 자료를 찾다가 알게 된 눈에 잘 띄는 패드로 학생 2의 패드 부착안을 보강했다.', '④ 적절하지 않다. 학생 4는 학생 1 발언의 "취지"에 동의했을 뿐이고 "공간상 문제로 계단 재시공이 어렵다"고 보아 실행 가능성이 낮음을 전제로 다른 대안(난간 보수)을 제시했다.', '⑤ 적절하다. 학생 1은 "노력과 비용이 적게 들면서도 문제를 개선할 수 있는 방법"이라며 효율성을 긍정적으로 평가했다.'],
    passage=P2, grp='H26-B', ref=[1], core='"취지에 동의"는 실행 가능성을 인정한다는 뜻이 아니다. 발언의 앞부분(공감)과 뒷부분(한계 지적)을 나누어 읽는다.')

add('H26-006', 'Ⅰ-B', '토의의 절차와 해결 방안 평가', '상',
    p('〈보기〉는 \'학생 3\'이 토의를 준비하며 수집한 자료이다. 자료를 모두 활용하여 [가]에 제시할 의견으로 가장 적절한 것은?') +
    bogi(['<b>[자료 1]</b> 후문 계단 안전사고 실태 파악을 위해 정리한 표',
          '연번 1 · 12.03. · 20:40 (일출 07:30, 일몰 17:19) / 연번 2 · 12.11. · 21:10 (일출 07:38, 일몰 17:18) / 연번 3 · 12.23. · 18:30 (일출 07:47, 일몰 17:14) / 연번 4 · 12.27. · 07:25 (일출 07:44, 일몰 17:21)',
          '<b>[자료 2]</b> 인터넷에서 \'조명\'을 검색하여 정리한 메모', '○ 가로등: 통행 및 보행 안전을 위해 길가를 따라 설치. ○ 센서등: 움직임을 감지하여 자동으로 켜짐. 상시 조명이 필요 없는 곳에 설치. ○ 잔디등: 상가 거리, 광장 주변 녹지에 설치. 야간 보행 안전 및 미관을 위해 설치.',
          '<b>[자료 3]</b> 조명과 관련된 정보를 검색하다가 읽게 된 신문 기사', '○○시에 따르면, 지난해에 빛 공해 관련 민원이 모두 227건 접수됐다. 특히 A 아파트에 대한 민원이 지속적으로 제기되고 있다. 인근 주민 B 씨는 "A 아파트의 외부 조명으로 인해 저녁부터 새벽까지 내내 집 안이 환해서 너무 힘듭니다."라며 "A 아파트가 준공되고 나서 지금까지 조명이 꺼진 적이 단 한 번도 없습니다."라고 말했다.']),
    ['후문 주택가 주민들이 빛 공해 문제를 겪지 않도록 학교 주변에 설치된 가로등의 조도를 낮추어 주는 것이 좋겠습니다.', '후문 계단이 낡아서 주변이 낙후된 느낌이니 잔디등을 설치하여 미관을 개선하면 후문으로 등하교하는 학생이 늘어날 것입니다.', '등교 시간에 안전사고가 주로 발생하므로 센서등을 설치하면 안전사고를 줄이면서 이른 아침에 인근 주민에게 피해도 주지 않을 것입니다.', '후문 계단에 가로등을 설치하고 일몰부터 일출까지 켜 두면 학생들도 안전하게 등하교할 수 있고 인근 주민들의 안전에도 도움이 될 것입니다.', '겨울철 어두울 때 후문 계단에서 안전사고가 발생하니 조명을 설치하되 후문 주택가 주민들의 빛 공해 문제를 고려해 센서등을 설치하면 좋겠습니다.'], 5,
    ['자료 1: 사고 4건이 모두 일몰 이후 또는 일출 이전(어두운 시간)에 일어났다. 자료 2: 센서등은 상시 조명이 필요 없는 곳에 설치한다. 자료 3: 조명을 계속 켜 두면 인근 주민에게 빛 공해 민원이 생긴다. → 어두울 때 안전을 확보하면서 빛 공해를 줄이는 센서등이 가장 적절하다.', '① 가로등의 조도를 낮추면 오히려 안전 문제를 키운다.', '② 사고 원인과 무관한 미관 개선만 다루었다.', '③ 자료 1에서 사고는 등교 시간이 아니라 주로 어두운 시간대에 일어났다.', '④ 가로등을 일몰부터 일출까지 켜 두면 자료 3의 빛 공해 문제를 간과하게 된다.'],
    passage=P2, grp='H26-B', ref=[1], core='자료를 모두 활용한 의견은 각 자료가 알려 주는 조건(시간대·시설의 특성·부작용)을 모두 만족해야 한다.')

# ---------------------------------------------------------------- [7~8] 토론
P3 = ('<p class="hd"><b>[7~8]</b> 다음은 토론의 일부이다.</p>' + ''.join('<p><b>%s</b> : %s</p>' % t for t in [
    ('사회자', '우리 학교 동아리 축제에서 동아리 홍보관은 신입 회원 모집을 위한 홍보 효과가 높기 때문에 동아리들에게 인기가 많습니다. 그러나 홍보관 설치를 위한 공간이 한정되어 있어, 지금까지는 학생회가 홍보관 운영 계획서를 공모하여 심사한 후 홍보관을 운영할 동아리를 선정해 왔습니다. 그런데 기존 방식인 <u>㉠심사 방식</u> 대신 새로운 방식으로 <u>㉡추첨 방식</u>을 요구하는 동아리들이 많이 있어, 이번 시간에는 \'동아리 축제에서 홍보관을 운영할 동아리를 선정할 때 추첨 방식으로 해야 한다.\'라는 논제로 토론을 하겠습니다. 찬성 측 입론해 주십시오.'),
    ('찬성 1', '동아리 축제에서 홍보관을 운영할 동아리를 선정할 때 추첨 방식으로 해야 합니다. 심사 방식의 평가 기준이 타당하지 않고, 평가자 주관이 개입될 수 있어 평가의 신뢰성이 낮아 학생들의 불만이 높기 때문입니다. 반면에 추첨 방식은 선정 과정에서 평가자의 견해가 반영될 수 없습니다. 또한 추첨 방식으로 한다면 홍보관 운영 동아리로 선정될 수 있는 기회가 모든 동아리에 균등하게 부여될 수 있습니다. 그리고 동아리 홍보관 운영 계획서를 준비하는 과정에서 동아리들이 시간과 노력을 불필요하게 들이는 문제도 해소할 수 있습니다.'),
    ('사회자', '이번에는 반대 측에서 반대 신문 해 주십시오.'),
    ('반대 2', '추첨 방식이 기회를 균등하게 부여한다고 말씀하셨는데, 그럴 경우 동아리 홍보관 운영을 더 잘 계획하고 준비한 동아리가 탈락할 수도 있죠. 준비가 덜 된 동아리가 선정된다면 동아리 홍보관 운영의 부실로 이어질 수 있지 않나요? <b>[A]</b>'),
    ('찬성 1', '그렇지 않습니다. 선정된 동아리들은 새로운 회원을 모집하기 위해 적극적으로 홍보해야 하므로, 홍보관 운영에 최선을 다할 것입니다.'),
    ('사회자', '이번에는 반대 측에서 입론해 주십시오.'),
    ('반대 1', '홍보관 운영 동아리 선정을 추첨 방식으로 하는 것에 반대합니다. 기존의 심사 방식은 전체 학생을 대표하는 다수의 평가자가 참여하여 평가자의 주관적 개입을 줄일 수 있고, 평가 기준 역시 매년 학생들의 의견을 수렴하여 개선해 왔기 때문에 그 타당성이 매우 높다고 할 수 있습니다. 또한 심사 방식은 모든 동아리가 홍보관 운영 계획서를 제출할 기회를 공평하게 부여하고 있습니다. 그리고 이 계획서를 준비하는 과정에서 동아리 구성원들이 동아리 축제의 목적에 부합하는 활동을 고민하게 되므로 축제가 내실화될 수 있습니다.'),
    ('사회자', '이번에는 찬성 측에서 반대 신문 해 주십시오.'),
    ('찬성 1', '홍보관 운영 계획서를 평가하는 기준이 타당하다고 하셨는데 작년 설문 조사 결과에 따르면 평가 기준 중의 일부가 특정 동아리에게 유리하게 작용한다고 응답한 학생들이 많았습니다. 이런 점에서 평가 기준이 타당하다고 보기 어렵지 않나요? <b>[B]</b>'),
    ('반대 1', '그 문제는 평가 기준의 일부를 개선하여 해결할 수 있습니다.')]))

add('H26-007', 'Ⅰ-B', '토론의 논제와 입론의 이해', '중', p('위 토론의 입론에 대한 이해로 가장 적절한 것은?'),
    ['\'찬성 1\'은 용어의 개념을 정의함으로써 논의의 범위를 한정하고 있다.', '\'찬성 1\'은 기존 방식이 유지될 때 발생하는 기대 효과를 중심으로 주장하고 있다.', '\'반대 1\'은 논제와 관련된 문제 해결의 시급성을 강조하고 있다.', '\'반대 1\'은 기존 방식의 긍정적 측면을 근거로 삼아 새로운 방식을 반대하고 있다.', '\'반대 1\'은 새로운 방식을 도입할 때 발생할 수 있는 부정적 측면에 대하여 언급하고 있다.'], 4,
    ['① 옳지 않다. 찬성 1은 용어의 개념을 정의하지 않았다.', '② 옳지 않다. 찬성 1은 기존 방식의 문제점과 추첨 방식의 장점을 주장했다. 기존 방식이 유지될 때의 기대 효과를 말한 것이 아니다.', '③ 옳지 않다. 문제 해결의 시급성을 강조한 부분은 없다.', '④ 옳다. 반대 1은 심사 방식의 평가자 다수 참여, 타당한 평가 기준, 공평한 기회, 축제 내실화라는 기존 방식의 긍정적 측면을 근거로 추첨 방식에 반대했다.', '⑤ 옳지 않다. 반대 1은 입론에서 추첨 방식을 도입할 때의 부정적 측면을 말하지 않았다(그 내용은 반대 신문 [A]에서 나온다).'],
    passage=P3, grp='H26-C', ref=[2], core='입론의 근거가 "기존 방식의 장점"인지 "새 방식의 단점"인지, 지문의 어느 문장에 있는지 확인한다.')

add('H26-008', 'Ⅰ-B', '반대 신문의 질문 의도', '상', p('[A]와 [B]에 대한 설명으로 가장 적절한 것은?'),
    ['[A]는 상대측이 제시한 사례가 적합한지에 대해 의문을 제기하고, 적합한 사례를 제시할 것을 요구하고 있다.', '[A]는 상대측이 앞서 진술한 내용의 일부를 확인하고, 기존 방식을 고수할 경우 생길 문제점을 제기하고 있다.', '[B]는 상대측 주장을 뒷받침하는 근거가 믿을 만한지 의문을 제기하고, 출처를 제시할 것을 요구하고 있다.', '[B]는 상대측이 언급한 내용의 일부를 확인하고, 설문 조사 결과를 근거로 평가 기준의 타당성에 대해 의문을 제기하고 있다.', '[A]와 [B] 모두 상대측이 인용한 전문가의 설명이 적합한지 따지고, 사실 관계를 확인하고 있다.'], 4,
    ['① 옳지 않다. [A]는 사례를 제시한 적이 없다. 추첨 방식의 문제점을 지적했다.', '② 옳지 않다. [A]는 "기회를 균등하게 부여한다고 말씀하셨는데"로 상대 진술의 일부를 확인했지만, 제기한 문제점은 기존 방식이 아니라 새 방식(추첨)을 도입할 때 생길 문제이다.', '③ 옳지 않다. [B]는 출처를 요구하지 않았고 오히려 설문 조사 결과를 제시했다.', '④ 옳다. [B]는 "평가 기준이 타당하다고 하셨는데"로 상대 진술을 확인하고 작년 설문 조사 결과를 근거로 평가 기준의 타당성에 의문을 제기했다.', '⑤ 옳지 않다. 두 발화 모두 전문가의 설명을 인용한 내용이 없다.'],
    passage=P3, grp='H26-C', ref=[3], core='반대 신문 발화는 앞부분(상대 진술의 확인)과 뒷부분(근거·문제 제기)으로 나누어 기능을 판단한다.')

# ---------------------------------------------------------------- [9~10] 대화
P4 = ('<p class="hd"><b>[9~10]</b> 다음은 생태 동아리 학생들의 대화이다. <b>(가)</b></p>' + ''.join('<p><b>%s</b> : %s</p>' % t for t in [
    ('학생 1', '<u>㉠지난 시간에는 녹지 공원 조성 아이디어 공모전에 참여하기로 결정했지?</u> 오늘은 아이디어를 구상해 보자.'),
    ('학생 2', '나는 사람이 관리하지 않고 자연 상태 그대로 두는 \'의도적 방치\'를 바탕으로 아이디어를 준비해 왔어. 생태 특강에서 들었던 건데, 공원의 일부를 의도적으로 돌보지 않는 구역으로 만드는 거야.'),
    ('학생 3', '<u>㉡의도적 방치가 가능한 거야? 그렇게 하면 어떤 점이 좋은데?</u>'),
    ('학생 2', '특정 구역을 의도적으로 방치하면 다양한 생물이 자라나고 유입되면서 역동적인 생태계가 만들어질 수 있어.'),
    ('학생 3', '그렇구나. 혹시 다른 장점도 있으면 알려 줘.'),
    ('학생 2', '잡초 제거 작업을 하지 않으니 녹지 공원 조성에 드는 비용이 줄어드는 효과가 있어.'),
    ('학생 1', '아, 그래? 제초제를 뿌리지 않으면 화학 물질로 인한 토양이나 수질 오염도 줄겠네. 그런데 의도적 방치 구역에서 생태계가 원래대로 돌아온 사례가 있어?'),
    ('학생 2', '○○시에서 △△섬에 사람의 출입을 제한했더니 습지 생태계가 복원되고 철새들이 돌아왔대.'),
    ('학생 3', '생각해 보니 다른 지자체에서 진행한 비슷한 사례를 들은 적이 있어.'),
    ('학생 1', '그렇구나. 그런데 우리 지역 공원에 그런 공간을 만들면 문제는 없을까?'),
    ('학생 2', '어수선하고 지저분한 공간으로 보일 수 있지. 녹지 공원 내 시민들이 여가를 즐길 수 있는 공간도 줄고……'),
    ('학생 3', '그래도 이런 시도가 필요하다고 생각해. 지금 당장은 불편할 수 있지만, 자연이 스스로 회복할 수 있도록 공원의 일부라도 자연에게 내어 준다면 장기적으로 시민들에게도 도움이 될 거야.'),
    ('학생 1', '<u>㉢동의해.</u> 그러면 공간을 방치만 하면 되는 거야?'),
    ('학생 2', '초반에는 사람이 최소한으로 개입해서 생태계가 정상적으로 돌아올 수 있는 조건을 만들어 주는 것이 필요하대.'),
    ('학생 1', '그러면 그런 조건을 어떻게 만들 수 있어?'),
    ('학생 2', '처음에는 대대로 우리 땅에서 자라 온 토착 식물을 심고, 사람들의 출입을 제한해 해당 구역을 보호하는 방법으로 그런 조건을 만들어 나가는 거래.'),
    ('학생 3', '<u>㉣다시 말하면 토착 식물을 심고, 그 공간에 사람 출입을 제한하는 거네.</u> 이 내용을 써서 공모전에 제안하자.'),
    ('학생 1', '<u>㉤그래 좋아.</u> 그런데 이 공모 아이디어를 제안하려면 추가 자료가 필요할 것 같아.'),
    ('학생 3', '내가 관련 전문가에게 인터뷰를 부탁해 볼게.'), ('학생 1', '고마워. 인터뷰 내용을 참고해서 우리 제안을 글로 써 볼게.')]))

P4B = ('<p class="hd"><b>(나)</b> 다음은 (가)의 대화 후 학생들이 한 인터뷰의 일부이다.</p>' + ''.join('<p><b>%s</b> : %s</p>' % t for t in [
    ('학생 2', '해외에서 의도적 방치로 생태계가 회복된 곳은 어디가 있을까요?'),
    ('전문가', '영국에서는 \'○○나무\'를 심은 구역을 방치함으로써 자연의 자생적 생태 과정을 활성화했고, 이를 통해 생태계가 복원된 사례가 있어요. 더 궁금한 거 있나요?'),
    ('학생 3', '그럼 의도적 방치 구역임을 어떻게 알려야 할까요?'),
    ('전문가', '방치가 의도된 것임을 알려 주는 \'돌봄의 신호\'를 보여 줄 필요가 있어요. 그 구역의 의미를 알리는 표지판이 \'돌봄의 신호\' 역할을 할 수 있어요.')]))

add('H26-009', 'Ⅰ-C', '대화의 흐름과 발화 의도', '상', p('대화의 흐름을 고려할 때, ㉠~㉤에 대한 이해로 적절하지 않은 것은?'),
    ['㉠: 지난 시간에 결정된 내용을 확인한 뒤, 대화의 목적을 밝히고 있다.', '㉡: 직전 발화 내용에 의문을 제기한 뒤, 궁금한 점에 대한 설명을 요청하고 있다.', '㉢: 직전 발화 내용을 정리한 뒤, 자신이 이해한 내용이 맞는지 확인하고 있다.', '㉣: 직전 발화 내용의 일부를 재진술한 뒤, 담화 참여자들에게 행동을 함께할 것을 요청하고 있다.', '㉤: 직전 발화 내용에 동의한 뒤, 자신의 의견을 덧붙이고 있다.'], 3,
    ['① 적절하다. 지난 시간에 정한 공모전 참여를 확인하고 "오늘은 아이디어를 구상해 보자"며 목적을 밝혔다.', '② 적절하다. "의도적 방치가 가능한 거야?"로 의문을 제기하고 "어떤 점이 좋은데?"로 설명을 요청했다.', '③ 적절하지 않다. ㉢은 직전 발화(학생 3)에 "동의해"라고 한 뒤 "공간을 방치만 하면 되는 거야?"라며 다음 단계를 물을 뿐, 직전 발화 내용을 정리하거나 이해한 내용을 확인하지 않는다.', '④ 적절하다. "다시 말하면"으로 학생 2의 말을 재진술하고 "공모전에 제안하자"며 함께 행동할 것을 청했다.', '⑤ 적절하다. 학생 3의 제안에 동의하고 "추가 자료가 필요할 것 같아"라고 의견을 덧붙였다.'],
    passage=P4 + P4B, grp='H26-D', ref=[1], core='동의 후 다음 단계를 묻는 발화는 정리·확인이 아니다. 정리·확인은 앞선 내용을 다시 말해 맞는지 묻는 것이다.')

add('H26-010', 'Ⅰ-C', '면담·인터뷰의 질문 전략', '상', p('다음은 (가)의 대화 후 학생들이 한 인터뷰의 일부이다. 참여자들의 의사소통 양상에 대한 설명으로 가장 적절한 것은?'),
    ['\'전문가\'는 인터뷰의 목적을 파악하기 위해, 질문 내용을 \'학생 2\'에게 되묻고 있다.', '\'전문가\'는 사례에 대한 \'학생 3\'의 이해를 돕기 위해, 개념의 이해 정도를 확인한 후 답변하고 있다.', '\'학생 2\'는 제안 내용의 근거를 보강하기 위해, 다른 나라의 경우를 예로 들어 답변할 것을 요청하고 있다.', '\'학생 3\'은 제안 내용의 공정성을 확보하기 위해, 찬반 관점 모두를 포함해 답변할 것을 요청하고 있다.', '\'학생 2\'와 \'학생 3\'은 모두, 제안의 채택 가능성을 높이기 위해, 제안 내용의 타당성을 검토해 답변할 것을 요청하고 있다.'], 3,
    ['① 옳지 않다. 전문가는 질문 내용을 되묻지 않고 바로 답했다("더 궁금한 거 있나요?"는 추가 질문 여부를 묻는 말이다).', '② 옳지 않다. 전문가는 개념의 이해 정도를 확인하지 않았다.', '③ 옳다. 학생 2는 공모 제안의 근거를 보강하려고 "해외에서 … 회복된 곳은 어디가 있을까요?"라며 다른 나라의 사례를 요청했다.', '④ 옳지 않다. 학생 3은 찬반 관점 모두를 요청하지 않았다(의도적 방치 구역임을 알리는 방법을 물었다).', '⑤ 옳지 않다. 학생 3의 질문은 제안의 타당성 검토 요청이 아니라 방치 구역임을 알리는 방법에 관한 것이다.'],
    passage=P4 + P4B, grp='H26-D', ref=[3], core='인터뷰 질문의 목적(근거 보강, 방법 확인 등)은 질문 내용에서 읽는다.')

# ---------------------------------------------------------------- [11~12] 협상
P5 = ('<p class="hd"><b>[11~12]</b> 다음은 협상 상황이다.</p>' + ''.join('<p><b>%s</b> : %s</p>' % t for t in [
    ('시청 담당자', '오늘은 Z동에 신축할 주민 복지 센터 3층 공간 활용에 대해 협상을 진행하겠습니다. 첫 협상에 이어 후속 협상에도 참여해 주신 Y동 대표님과 Z동 대표님께 감사드립니다.'),
    ('Y동 대표', '우리 동은 학령 인구 비율이 높지만 아이들이 책을 읽고 공부할 수 있는 공간이 부족합니다. 그래서 도서관 건립을 지속적으로 건의해 왔습니다. 시청의 선호도 조사에서도 우리 동 주민들의 1순위는 도서관이었습니다. Z동에 주민 복지 센터가 지어지는 만큼 3층 공간에 대해서는 우리 동의 의견을 따라 주시면 좋겠습니다.'),
    ('Z동 대표', '우리 동에서도 도서관을 선호하는 의견은 있었습니다. 하지만 우리 동은 중장년층 인구 비율이 높아 체육 시설의 필요성이 더 큽니다. 선호도 조사에서도 체육 시설을 가장 선호하는 것으로 나타났습니다. 이 점을 고려하여 체육 시설을 마련하면 좋겠습니다.'),
    ('Y동 대표', '저희도 Z동의 상황을 알고 있습니다. 현재 진행 중인 저희 동의 체육 시설 확장 공사가 마무리되면 Z동의 중장년층 주민들도 편리하게 이용할 수 있을 것입니다. <u>㉠그러니 주민 복지 센터에 도서관을 만들면 두 동에 필요한 시설을 다 갖추게 되어 모두에게 이득이 되지 않을까요?</u>'),
    ('Z동 대표', '물론 두 시설을 다 이용할 수 있으면 좋습니다. 하지만 Y동의 체육 시설과 우리 동 사이의 거리가 멀고 교통편도 불편합니다. 주민 복지 센터로 연결되는 시설 버스 노선이 체육 시설에도 연결되도록 조정하는 추가 조치도 있어야 합니다.'),
    ('시청 담당자', '그 문제는 버스 회사와 협의해야 하는 문제이고, 조정도 쉽지 않습니다.'),
    ('Z동 대표', '그러면 체육 시설을 통한 수익 증가가 예상되는 Y동에서 비용을 부담해 주시는 것은 어떻습니까?'),
    ('Y동 대표', '이번 협상을 준비하면서 우리 동에서 양보할 수 있는 부분에 대해 주민들과 의견을 나누었습니다. 우리 체육 시설에서 운영하는 무료 셔틀버스를 Z동까지 운행하는 것은 가능합니다.'),
    ('Z동 대표', '그뿐만 아니라 Y동의 체육 시설 이용료는 기존 복지 센터 내 체육 시설 이용료보다 비쌉니다. <u>㉡Y동 입장에서는 이용자 증가로 더 큰 수익을 얻을 수 있지만, 우리 동 주민들은 체육 시설 이용에 대한 부담이 더 커질 것이므로 요금에 대한 부담을 낮춰 주십시오.</u>'),
    ('Y동 대표', '도서관을 설치하는 것에 동의해 주신다면 Z동 주민에게 우리 동 주민과 동일한 수준의 요금 할인을 적용하겠습니다.'),
    ('Z동 대표', '네, 동의하겠습니다.'),
    ('시청 담당자', '그럼 3층에 도서관을 설치하는 것으로 협상이 타결되었습니다. 세부 추진 방법은 차후에 논의하겠습니다. 참여해 주셔서 감사합니다.')]))

add('H26-011', 'Ⅰ-C', '협상 발화의 기능', '상', p('협상 진행 과정을 고려할 때, ㉠, ㉡에 대한 설명으로 가장 적절한 것은?'),
    ['㉠은 도서관 설치와 관련해 양보할 수 있는 범위를 제시하여 상대의 제안과 절충을 시도하는 발화이다.', '㉠은 체육 시설에 대한 상대의 제안을 일부 수용하여 자신의 제안을 조정함으로써 상대의 양보를 이끌어 내는 발화이다.', '㉡은 체육 시설 설치가 실현 가능성이 낮음을 들어 자신의 이익을 극대화하는 발화이다.', '㉡은 체육 시설 이용에 대한 상대의 요구 사항을 언급하며 자신이 양보 가능한 범위를 제시하는 발화이다.', '㉡은 체육 시설 이용 시 예상되는 상대의 이익과 자신의 부담을 언급하며 추가적인 요구 사항을 제시하는 발화이다.'], 5,
    ['① 옳지 않다. ㉠은 양보 가능 범위를 제시하며 상대 제안과 절충하려는 발화가 아니라, Y동의 체육 시설을 활용하자는 근거로 도서관 설치를 다시 주장하는 발화이다.', '② 옳지 않다. ㉠은 상대(Z동)의 체육 시설 제안을 수용하지 않고 도서관 설치를 설득하며 자신의 입장을 유지한다.', '③ 옳지 않다. ㉡은 체육 시설 설치의 실현 가능성을 말하지 않았다. 이미 있는 Y동 체육 시설의 이용료 문제를 다루었다.', '④ 옳지 않다. ㉡은 자신이 양보할 수 있는 범위를 제시하지 않고 오히려 상대(Y동)에게 요금 인하를 요구했다.', '⑤ 옳다. ㉡은 "Y동 입장에서는 이용자 증가로 더 큰 수익"이라는 상대의 이익과 "우리 동 주민들은 … 부담이 더 커질 것"이라는 자신의 부담을 언급하며 요금 인하라는 추가 요구를 제시했다.'],
    passage=P5, grp='H26-E', ref=[2], core='협상 발화는 양보·절충·요구·설득 중 어느 기능인지, 누구의 이익과 부담을 언급하는지로 판단한다.')

add('H26-012', 'Ⅰ-C', '매체 자료의 작성과 활용', '중',
    p('〈보기〉는 위 협상을 취재한 기자가 쓴 기사이다. 〈보기〉를 작성할 때 고려한 내용으로 적절하지 않은 것은?') +
    bogi(['Y동과 Z동의 주민 대표는 신설될 주민 복지 센터에 도서관을 설치하기로 합의했다. 신설 센터의 공간 활용에 대한 두 동의 의견 차이를 조정하기 위한 협상이 지난달 30일 오후 2시에 시청 회의실에서 개최되었다.',
          '협상은 다음과 같이 진행되었다. Y동 대표가 지역에 학령 인구 비율이 높아서 도서관 설치가 필요하다고 하자, Z동 대표는 중장년층 비율이 높아 체육 시설이 필요하다고 밝혔다. 양측의 입장 차는 Y동 체육 시설의 활용이 대안으로 떠오르면서 좁혀지기 시작했으며, 세부적인 조건의 조율을 거쳐 합의가 도출되었다.']),
    ['독자들이 협상이 개최된 장소와 시간을 파악할 수 있도록 한다.', '독자들이 합의가 도출되기까지의 협상의 경과를 확인할 수 있도록 한다.', '독자들이 기사의 중심 내용인 협상의 결과를 도입부에서 파악할 수 있도록 한다.', '독자들이 기사에 인용된 내용을 바탕으로 협상에 참여한 두 동 대표의 입장을 파악할 수 있도록 한다.', '독자들이 기사에 언급된 필자의 의견을 통해 협상의 결과가 Y동과 Z동 주민에게 중요한 사안임을 확인할 수 있도록 한다.'], 5,
    ['① 고려했다. "지난달 30일 오후 2시에 시청 회의실"이 있다.', '② 고려했다. 둘째 문단이 협상의 진행 경과를 서술한다.', '③ 고려했다. 첫 문장이 협상의 결과(도서관 설치 합의)를 먼저 밝힌다.', '④ 고려했다. 기사에서 두 대표의 입장(학령 인구 비율이 높아 도서관 필요 / 중장년층 비율이 높아 체육 시설 필요)이 서술되어 독자가 입장을 파악할 수 있다.', '⑤ 고려하지 않았다. 기사에는 필자의 의견(평가·주장)이 없고 사실만 서술되어 있다.'],
    passage=P5, grp='H26-E', ref=[3], core='기사 판단은 선택지의 요소(장소·시간, 경과, 결과, 입장, 필자 의견)가 기사에 문장 근거로 있는지 확인한다.')
